import{R as e,Z as t,o as n,z as r}from"./chunks/framework.RooERd0G.js";var i=JSON.parse(`{"title":"Game Mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/game-mechanics.md","filePath":"guide/game-mechanics.md"}`),a={name:`guide/game-mechanics.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="game-mechanics" tabindex="-1">Game Mechanics <a class="header-anchor" href="#game-mechanics" aria-label="Permalink to &quot;Game Mechanics&quot;">​</a></h1><p>Welcome to the Game Mechanics guide. This documentation is automatically generated from the latest game features.</p><h2 id="match-rules-viewer" tabindex="-1">Match Rules Viewer <a class="header-anchor" href="#match-rules-viewer" aria-label="Permalink to &quot;Match Rules Viewer&quot;">​</a></h2><p>Every match type has a built-in rules reference. Tap the info button on any segment or the How to Play button during a match to view solo and multiplayer rule summaries without leaving the app.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-match-info.png" alt="Match Rules Viewer"></p><hr><h2 id="weekly-challenges" tabindex="-1">Weekly Challenges <a class="header-anchor" href="#weekly-challenges" aria-label="Permalink to &quot;Weekly Challenges&quot;">​</a></h2><p>Browse official and custom weekly challenges. Filter by official status or required expansions and open any challenge for full setup instructions, conditions, and modifiers.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-weekly-challenges.png" alt="Weekly Challenges"></p><hr><h2 id="wrestler-abilities-in-match" tabindex="-1">Wrestler Abilities in Match <a class="header-anchor" href="#wrestler-abilities-in-match" aria-label="Permalink to &quot;Wrestler Abilities in Match&quot;">​</a></h2><p>Your wrestler&#39;s ability board is always a tap away during a match. The collapsed &#39;Your Abilities&#39; panel in the match sidebar shows your core, wrestler-specific, and unlockable abilities with their type badges and [[token]] icon descriptions — no need to leave the match to look something up.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-match-abilities.png" alt="Wrestler Abilities in Match"></p><hr><h2 id="ability-reminders" tabindex="-1">Ability Reminders <a class="header-anchor" href="#ability-reminders" aria-label="Permalink to &quot;Ability Reminders&quot;">​</a></h2><p>The match view reminds everyone at the table what each wrestler&#39;s abilities do. Participant cards carry compact ability chips with trigger tooltips, and the player&#39;s own panel shows when each ability fires (color-coded by offense/defense/pinned), an advisory uses-left counter, and a Mark Used button that logs the usage into the match notes — feeding the AI narration and match summary. Nothing is enforced: the table remains the authority.</p><p><img src="/all-time-wrestling-rpg/screenshots/match-ability-reminders.png" alt="Ability Reminders"></p><hr><h2 id="contender-matches" tabindex="-1">Contender Matches <a class="header-anchor" href="#contender-matches" aria-label="Permalink to &quot;Contender Matches&quot;">​</a></h2><p>Mark any match as a #1 Contender Match to put the next title shot on the line. The segment carries a gold star badge on the show card, the winner is automatically designated as the title&#39;s #1 contender, and the match earns bonus rivalry heat and fan gains.</p><p><img src="/all-time-wrestling-rpg/screenshots/contender-match-badge.png" alt="Contender Matches"></p><hr><h2 id="tournament-bracket" tabindex="-1">Tournament Bracket <a class="header-anchor" href="#tournament-bracket" aria-label="Permalink to &quot;Tournament Bracket&quot;">​</a></h2><p>The full projected 4-round bracket (Round 1 through Quarter-Final, Semi-Final and Final): connector lines between rounds, decided winners advancing (replacing &#39;Winner of Match N&#39; placeholders), losers struck through, and Fit/100% zoom controls.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-tournament-bracket.png" alt="Tournament Bracket"></p><hr><h2 id="money-in-the-bank-briefcase" tabindex="-1">Money in the Bank Briefcase <a class="header-anchor" href="#money-in-the-bank-briefcase" aria-label="Permalink to &quot;Money in the Bank Briefcase&quot;">​</a></h2><p>A briefcase-deciding tournament (like the annual Time Vault) pays off with a cashable briefcase instead of a championship: the detail view shows the payoff mode and the winner&#39;s briefcase status (held with its cashable-until date, cashed in, or expired).</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-briefcase-tournament.png" alt="Money in the Bank Briefcase"></p><hr><h2 id="cash-in-the-briefcase" tabindex="-1">Cash In the Briefcase <a class="header-anchor" href="#cash-in-the-briefcase" aria-label="Permalink to &quot;Cash In the Briefcase&quot;">​</a></h2><p>The holder&#39;s career view shows the held briefcase with its expiry and a Cash In action: pick any active championship with a reigning champion and a show, and the title match books on the spot. The briefcase is spent whether the match is won or lost.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-briefcase-cash-in.png" alt="Cash In the Briefcase"></p><hr><h2 id="briefcase-on-the-wrestler-profile" tabindex="-1">Briefcase on the Wrestler Profile <a class="header-anchor" href="#briefcase-on-the-wrestler-profile" aria-label="Permalink to &quot;Briefcase on the Wrestler Profile&quot;">​</a></h2><p>The wrestler profile carries the same Briefcase panel — held case, cashable-until date, and the Cash In action — next to Championships, so the prize is visible without leaving the profile. The Career Dashboard link in the hero section leads to the full career history.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-briefcase-profile.png" alt="Briefcase on the Wrestler Profile"></p><hr><h2 id="briefcase-management" tabindex="-1">Briefcase Management <a class="header-anchor" href="#briefcase-management" aria-label="Permalink to &quot;Briefcase Management&quot;">​</a></h2><p>Bookers manage the Money in the Bank-style briefcases from the Entities menu: every case with its holder, division, status and cashable-until date. Live (HELD) cases can be edited — rename, override the expiry, upload artwork — or voided (a manual cancel that keeps the row as history). Cashed-in and expired rows are read-only history.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-briefcase-crud.png" alt="Briefcase Management"></p><hr><h2 id="team-tournaments" tabindex="-1">Team Tournaments <a class="header-anchor" href="#team-tournaments" aria-label="Permalink to &quot;Team Tournaments&quot;">​</a></h2><p>Tournaments can be crowned with team champions: pick Tag Team or Trios entrants and the seeding step swaps the wrestler picker for a team registry — active, seeded teams of the declared size (DUO/TRIO) filtered by the gender restriction, sorted by team fans. The linked championship must be a TEAM title, and the payoff always puts it on the line: the winning team becomes the inaugural champions.</p><p><img src="/all-time-wrestling-rpg/screenshots/team-tournament-wizard.png" alt="Team Tournaments"></p><hr><h2 id="team-tournaments-—-one-off-assembly" tabindex="-1">Team Tournaments — One-Off Assembly <a class="header-anchor" href="#team-tournaments-—-one-off-assembly" aria-label="Permalink to &quot;Team Tournaments — One-Off Assembly&quot;">​</a></h2><p>Prefer a team that is not in the registry? Assemble one right in the wizard with the add-team rows: each row is one team accepting exactly the declared member count (a duo row takes two picks), &quot;+ Add Team&quot; adds another, and every picker excludes wrestlers already committed to a picked registry team or another row. Team names are generated from the lineups and uniquified on create. The assembled teams persist as one-off (AD_HOC) teams unless &#39;Save these teams to the team registry&#39; is checked (default off), which flips them into the registry for future tournaments.</p><p><img src="/all-time-wrestling-rpg/screenshots/team-tournament-one-off-assembly.png" alt="Team Tournaments — One-Off Assembly"></p><hr><h2 id="cards" tabindex="-1">Cards <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;Cards&quot;">​</a></h2><p>The heart of the ATW RPG battle system. Each card represents a move (Strike, Grapple, Aerial, Throw) with specific health and stamina costs and damage effects.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-cards.png" alt="Cards"></p><hr><h2 id="decks" tabindex="-1">Decks <a class="header-anchor" href="#decks" aria-label="Permalink to &quot;Decks&quot;">​</a></h2><p>Manage wrestler-specific decks. Strategy involves balancing high-damage finishers with efficient setup moves and stamina-recovering taunts.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-decks.png" alt="Decks"></p><hr><h2 id="faction-synergy" tabindex="-1">Faction Synergy <a class="header-anchor" href="#faction-synergy" aria-label="Permalink to &quot;Faction Synergy&quot;">​</a></h2><p>Factions grow stronger as members work together. Affinity builds through shared matches and victories, unlocking powerful synergy buffs like stamina recovery, finisher damage, and resilience bonuses. High-affinity factions have a mechanical advantage in match outcomes.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-faction-synergy.png" alt="Faction Synergy"></p><hr><h2 id="persistent-wear-tear" tabindex="-1">Persistent Wear &amp; Tear <a class="header-anchor" href="#persistent-wear-tear" aria-label="Permalink to &quot;Persistent Wear &amp; Tear&quot;">​</a></h2><p>Matches take a toll on a wrestler&#39;s body. Physical condition degrades over time based on match intensity (Extreme matches double the wear) and positioning (Main Events are more demanding). Low condition results in health penalties and potential forced retirement.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-wear-and-tear.png" alt="Persistent Wear &amp; Tear"></p><hr><h2 id="expansion-packs" tabindex="-1">Expansion Packs <a class="header-anchor" href="#expansion-packs" aria-label="Permalink to &quot;Expansion Packs&quot;">​</a></h2><p>The roster is modular. Content is grouped into Expansion Packs that can be enabled or disabled by administrators. This dynamic system automatically filters wrestlers, teams, and factions based on active sets, allowing for themed seasons and customized gameplay experiences.</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-expansion-packs.png" alt="Expansion Packs"></p><hr><h2 id="ringside-actions" tabindex="-1">Ringside Actions <a class="header-anchor" href="#ringside-actions" aria-label="Permalink to &quot;Ringside Actions&quot;">​</a></h2><p>Managers and faction members can swing the match in your favor. Perform ringside actions like coaching, distracting the referee, or sliding in a weapon, but be careful - too much illegal interference will lead to ejections or disqualification!</p><p><img src="/all-time-wrestling-rpg/screenshots/mechanic-ringside-actions.png" alt="Ringside Actions"></p><hr>`,74)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};